begin;

do $$
declare dolu_sayisi int;
begin
  select count(*) into dolu_sayisi from public.madde_kutuphanesi
  where madde_id in ('MAD-0755','MAD-0756','MAD-0757','MAD-0758','MAD-0759','MAD-0760','MAD-0761','MAD-0762','MAD-0763','MAD-0764','MAD-0765','MAD-0766','MAD-0767','MAD-0768','MAD-0769','MAD-0770','MAD-0771','MAD-0772','MAD-0773','MAD-0774','MAD-0775','MAD-0776','MAD-0777','MAD-0778','MAD-0779','MAD-0780','MAD-0781','MAD-0782','MAD-0783','MAD-0784','MAD-0785','MAD-0786','MAD-0787','MAD-0788','MAD-0789','MAD-0790','MAD-0792','MAD-0793','MAD-0794','MAD-0795','MAD-0796','MAD-0797','MAD-0798','MAD-0799','MAD-0800','MAD-0801','MAD-0802','MAD-0803','MAD-0804','MAD-0805','MAD-0806','MAD-0807','MAD-0808','MAD-0810','MAD-0811','MAD-0812','MAD-0813','MAD-0814','MAD-0815','MAD-0816','MAD-0818','MAD-0819','MAD-0820','MAD-0821','MAD-0822','MAD-0823','MAD-0824','MAD-0825','MAD-0827','MAD-0828','MAD-0829','MAD-0830','MAD-0831','MAD-0832','MAD-0833','MAD-0834','MAD-0835','MAD-0836','MAD-0837','MAD-0838','MAD-0839','MAD-0840') and resmi_madde_metni is not null;
  if dolu_sayisi <> 0 then
    raise exception 'Beklenmeyen durum: % satirda resmi_madde_metni zaten dolu (fail-fast)', dolu_sayisi;
  end if;
end $$;

update public.madde_kutuphanesi set resmi_madde_metni = 'Merdivenler denge ayaklı olmaksızın EN 131-1:2015+A1:2019’e uygun olmalı ve normal bakım çalışmaları sırasında takılma tehlikesi olmayacak ve güvenli şekilde yerleştirilecek bir konumda bulunmalıdır.', kontrol_basligi = 'Merdivenlerin EN 131-1''e uygunluğu ve güvenli konumu', denetci_yonlendirmesi = 'Merdivenlerin denge ayaksız EN 131-1:2015+A1:2019''e uygun olduğunu ve takılma tehlikesi oluşturmayacak güvenli bir konumda bulunduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0755';
update public.madde_kutuphanesi set resmi_madde_metni = 'Merdiven, muhafaza edilen konumda değil ise asansörün çalışmasını engellemek için EN 81- 20, 5.11.2’ye uygun olan elektrikli güvenlik aygıtı/aygıtları sağlanmalıdır.', kontrol_basligi = 'Muhafaza dışı merdiven için elektrikli güvenlik aygıtı', denetci_yonlendirmesi = 'Merdiven muhafaza konumunda değilse, asansörün çalışmasını engelleyen EN 81-20 5.11.2''ye uygun elektrikli güvenlik aygıtı bulunduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0756';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kurtarma prosedürlerine uygun olarak kabin ile kabin tavanı arasında taşınabilir bir merdiven sağlandığı durumlarda, bu merdivenin boyu kabin boyundan en az 1 m uzun olmalı ve merdiven, imdat geçiş kapısı açıklığının kısa tarafında olmalıdır.', kontrol_basligi = 'Taşınabilir merdivenin boyu ve konumu', denetci_yonlendirmesi = 'Kabin-kabin tavanı arası taşınabilir merdivenin kabin boyundan en az 1 m uzun olduğunu ve imdat geçiş kapısı açıklığının kısa tarafında yer aldığını ölçün.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0757';
update public.madde_kutuphanesi set resmi_madde_metni = 'Taşınabilir merdivenlerin en büyük uzunluğu 6 m’dir. Merdiven, ana durak kapılarına dayanmamalı ve kabin tavanındaki uygun noktalardan desteklenmelidir. Ana durak kapısının/kapılarının tek elle açılması mümkün olmalıdır.', kontrol_basligi = 'Taşınabilir merdiven azami uzunluğu ve desteklenmesi', denetci_yonlendirmesi = 'Taşınabilir merdivenin en fazla 6 m olduğunu, ana durak kapılarına dayanmadığını, kabin tavanından desteklendiğini ve ana durak kapısının tek elle açılabildiğini kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0758';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kurtarma araçları olarak, seyyar merdivenler veya kurtarma araçları için güvenli sabitleme noktalarının her bir durak kapısının çevresinde sağlandığı güvenlik halatı sistemleri kullanılabilir.', kontrol_basligi = 'Kurtarma için seyyar merdiven veya güvenlik halatı sistemi', denetci_yonlendirmesi = 'Kurtarma aracı olarak seyyar merdiven veya her durak kapısı çevresinde güvenli sabitleme noktalı güvenlik halatı sistemi bulunduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0759';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kabin tavanından kabine iniş sağlayacak bir merdiven temin edilmelidir. Bu merdiven uygun olmalı ve kabin tavanından yerleştirilmelidir ve kabin içinden kurtarma amacıyla kullanılan merdivenle aynı olabilir.**', kontrol_basligi = 'Kabin tavanından kabine iniş merdiveni', denetci_yonlendirmesi = 'Kabin tavanından kabine inişi sağlayan uygun bir merdivenin temin edildiğini kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0760';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kabin içinden imdat geçiş kapısının ardına kadar açılması için erişim sağlanmalıdır.', kontrol_basligi = 'İmdat geçiş kapısına kabin içinden erişim', denetci_yonlendirmesi = 'Kabin içinden imdat geçiş kapısının ardına kadar açılacak erişimin sağlandığını kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0761';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kabin tavanına doğru yükselmek için bir merdiven veya basma yerleri sağlanmalı ve bunlar imdat geçiş kapısı açıklığının kısa tarafında konumlandırılmalıdır.', kontrol_basligi = 'Kabin tavanına yükselme merdiveni/basma yerleri konumu', denetci_yonlendirmesi = 'Kabin tavanına yükselmek için merdiven veya basma yerlerinin, imdat geçiş kapısı açıklığının kısa tarafında konumlandırıldığını kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0762';
update public.madde_kutuphanesi set resmi_madde_metni = 'Basma yerlerinin bulunduğu durumlarda, basamak yüksekliği en fazla 0,4 m olmalı, basma yeri 1 500 N’luk bir yüke dayanabilmeli ve basma yerleri ile düşey duvar arasındaki serbest mesafe en az 0,15 m olmalıdır.', kontrol_basligi = 'Basma yeri yüksekliği, yük dayanımı ve serbest mesafesi', denetci_yonlendirmesi = 'Basma yeri yüksekliğinin en fazla 0,4 m, yük dayanımının en az 1500 N ve düşey duvara serbest mesafesinin en az 0,15 m olduğunu ölçün.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0763';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kuyunun içindeki her bir durak girişinde kilide yakın olacak şekilde, durak kapısının nasıl açılacağını açıkça gösteren basit bir şema veya simge bulunmalıdır.', kontrol_basligi = 'Durak kapısı açma şeması/simgesi', denetci_yonlendirmesi = 'Her durak girişinde kilide yakın, durak kapısının nasıl açılacağını gösteren şema veya simge bulunduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0764';
update public.madde_kutuphanesi set resmi_madde_metni = 'Asansörün bütün hareketi boyunca engellenebileceği her bir konum için, 5.4.3 (kabinin dışından kurtarma) ve 5.4.4 (kabin içinden kendi kendine kurtulma)’te tanımlanan kurtarma prosedürleri mevcut olmalıdır.', kontrol_basligi = 'Her konum için kurtarma prosedürlerinin mevcudiyeti', denetci_yonlendirmesi = 'Asansörün durabileceği her konum için kabin dışından (5.4.3) ve kabin içinden (5.4.4) kurtarma prosedürlerinin mevcut olduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0765';
update public.madde_kutuphanesi set resmi_madde_metni = 'Yatay hareket eden sürmeli, otomatik (karşılıklı çalışan) çalışan kabin ve durak kapıları kullanılmalıdır.', kontrol_basligi = 'Kabin ve durak kapılarının yatay sürmeli otomatik tipte olması', denetci_yonlendirmesi = 'Kabin ve durak kapılarının yatay hareketli, sürmeli, otomatik (karşılıklı çalışan) tipte olduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0766';
update public.madde_kutuphanesi set resmi_madde_metni = 'Tahrik makinesi ve ilgili donanımı içeren bölme; en az, asansör kuyusu ile aynı yangın koruma seviyesinde olmalıdır.', kontrol_basligi = 'Tahrik makinesi bölmesinin yangın koruma seviyesi', denetci_yonlendirmesi = 'Tahrik makinesi ve ilgili donanımı içeren bölmenin en az asansör kuyusuyla aynı yangın koruma seviyesinde olduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0767';
update public.madde_kutuphanesi set resmi_madde_metni = 'Makinelerin bulunduğu herhangi bir alan, kuyu ve yangın bölmesinin dışında ise, yangın bölmesi/bölmeleri ile aynı yangın koruma seviyesinde korunmalıdır.', kontrol_basligi = 'Kuyu/yangın bölmesi dışındaki makine alanının korunması', denetci_yonlendirmesi = 'Makine alanı kuyu ve yangın bölmesinin dışındaysa, yangın bölmesiyle aynı yangın koruma seviyesinde korunduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0768';
update public.madde_kutuphanesi set resmi_madde_metni = 'İtfaiyeci asansörü anahtarı itfaiye hizmeti erişim seviyesi olarak kullanılması amaçlanan emniyetli alanda yer almalıdır. Anahtar, itfaiyeci asansöründen yatay olarak en fazla 2 m uzaklıkta ve zemin seviyesi üzerinden 1,4 m ila 2,0 m yükseklikte yer almalıdır. Anahtar, Ek G’ye uygun olarak itfaiyeci asansörü piktogramı ile işaretlenmeli ve bu piktogramın hangi asansörle ilişkilendirilmiş olduğu açıkça belirtilmelidir.', kontrol_basligi = 'İtfaiyeci anahtarının konumu, yüksekliği ve piktogram işaretlemesi', denetci_yonlendirmesi = 'İtfaiyeci asansörü anahtarının emniyetli alanda, asansörden en fazla 2 m uzaklıkta, zeminden 1,4-2,0 m yükseklikte ve piktogramla işaretli olduğunu ölçün.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0769';
update public.madde_kutuphanesi set resmi_madde_metni = 'itfaiyeci asansörü piktogramı; Gösterim beyaz renktedir.Arka plan kırmızı renktedir.Yangın söndürme çalışmalarında kullanılacak, kabin kumanda panosundaki bir simge için 20 mm * 20 mm;Bir durakta en az 100 mm * 100 mm.', kontrol_basligi = 'İtfaiyeci asansörü piktogramının renk ve boyutu', denetci_yonlendirmesi = 'Piktogramın beyaz üzerine kırmızı zeminde, kabin panosunda en az 20x20 mm, durakta en az 100x100 mm boyutunda olduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0770';
update public.madde_kutuphanesi set resmi_madde_metni = 'Anahtarın çalışma konumları, iki konumda kararlı şekilde olmalı ve açıkça ''1'' ve ''0'' ile işaretlenmelidir. Anahtarın hangi konumda olduğu gösteren net bir görsel gösterge bulunmalıdır. ''1'' konumunda, yangın söndürme çalışması başlatılmalıdır.', kontrol_basligi = 'Anahtarın ''1''/''0'' konum işaretlemesi ve göstergesi', denetci_yonlendirmesi = 'Anahtarın iki kararlı konumda ''1'' ve ''0'' olarak işaretli olduğunu, konum göstergesinin net olduğunu ve ''1'' konumunda yangın söndürme çalışmasının başladığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0771';
update public.madde_kutuphanesi set resmi_madde_metni = 'İtfaiyeci asansörü anahtarı çalıştırıldığında, kapının hareket yönünü değiştirme aygıtları hariç, asansöre ait tüm güvenlik aygıtları (elektrikli ve mekanik) çalışır durumda kalmalıdır.', kontrol_basligi = 'Anahtar çalıştırıldığında güvenlik aygıtlarının aktif kalması', denetci_yonlendirmesi = 'İtfaiyeci anahtarı çalıştırıldığında, kapı yön değiştirme aygıtları hariç tüm güvenlik aygıtlarının çalışır durumda kaldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0772';
update public.madde_kutuphanesi set resmi_madde_metni = 'İtfaiyeci asansörü anahtarı, elektrikli emniyet aygıtını, bakım amaçlı çalıştırmayı (bk. EN 81-20:2020, 5.12.1.5) veya acil durumda elektrikle çalıştırmayı (bk. EN 81-20:2020, 5.12.1.6) devre dışı bırakmamalıdır.', kontrol_basligi = 'Anahtarın bakım/acil çalıştırmayı devre dışı bırakmaması', denetci_yonlendirmesi = 'İtfaiyeci anahtarının, elektrikli emniyet aygıtını, bakım amaçlı çalıştırmayı veya acil durumda elektrikle çalıştırmayı devre dışı bırakmadığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0773';
update public.madde_kutuphanesi set resmi_madde_metni = 'Asansör normal çalışma durumundayken, itfaiyeci asansörü anahtarı ile asansör kumanda sistemi arasındaki arayüz bağlantısının kesilmesi, aşama 1’i başlatmalıdır.', kontrol_basligi = 'Arayüz bağlantısı kesilince Aşama 1''in başlaması', denetci_yonlendirmesi = 'Normal çalışmada itfaiyeci anahtarı ile kumanda sistemi arasındaki bağlantı kesildiğinde Aşama 1''in başladığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0774';
update public.madde_kutuphanesi set resmi_madde_metni = 'İtfaiyeci asansörü anahtarının başlatılmasıyla (elle veya otomatik olarak) kuyu ve makinenin bulunduğu alanlar otomatik olarak aydınlanmalıdır.(Aşama 1)', kontrol_basligi = 'Aşama 1''de kuyu/makine alanı otomatik aydınlatması', denetci_yonlendirmesi = 'Aşama 1 başlatıldığında kuyu ve makine alanının otomatik olarak aydınlandığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0775';
update public.madde_kutuphanesi set resmi_madde_metni = 'Aşama 1 in elle veya otomatik olarak çalıştırılması sonrasında, bütün duraklardaki kumandalar ve itfaiyeci asansörü kabinindeki kumandalar devre dışı bırakılmalı ve tüm mevcut kayıtlı çağrılar iptal edilmelidir.', kontrol_basligi = 'Aşama 1''de durak/kabin kumandalarının devre dışı kalması', denetci_yonlendirmesi = 'Aşama 1''de tüm durak ve kabin kumandalarının devre dışı bırakıldığını ve kayıtlı çağrıların iptal edildiğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0776';
update public.madde_kutuphanesi set resmi_madde_metni = 'Aşama 1 in elle veya otomatik olarak çalıştırılması sonrasında, kapı açma ve acil durum alarm düğmeleri çalışır durumda olmalıdır.', kontrol_basligi = 'Aşama 1''de kapı açma ve alarm düğmelerinin çalışır kalması', denetci_yonlendirmesi = 'Aşama 1''de kapı açma ve acil durum alarm düğmelerinin çalışır durumda kaldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0777';
update public.madde_kutuphanesi set resmi_madde_metni = 'Aşama 1 in elle veya otomatik olarak çalıştırılması sonrasında, itfaiyeci asansörü, diğer tüm asansörlerden bağımsız olarak çalışmalıdır.', kontrol_basligi = 'Aşama 1''de itfaiyeci asansörünün bağımsız çalışması', denetci_yonlendirmesi = 'Aşama 1''de itfaiyeci asansörünün diğer tüm asansörlerden bağımsız çalıştığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0778';
update public.madde_kutuphanesi set resmi_madde_metni = 'Aşama 1 in elle veya otomatik olarak çalıştırılması sonrasında, itfaiye haberleşme sistemi çalışır duruma getirilmelidir.', kontrol_basligi = 'Aşama 1''de itfaiye haberleşme sisteminin devreye girmesi', denetci_yonlendirmesi = 'Aşama 1''de itfaiye haberleşme sisteminin çalışır duruma getirildiğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0779';
update public.madde_kutuphanesi set resmi_madde_metni = 'Aşama 1 in elle veya otomatik olarak çalıştırılması sonrasında, İtfaiyeci asansörü için piktogram ve kabindeki kumanda panosunda yer alan görsel bir sinyal aktifleştirilmelidir. Asansör normal çalışma durumuna gelene kadar görsel sinyal aktif kalmalıdır.', kontrol_basligi = 'Aşama 1''de piktogram/görsel sinyalin aktifleşmesi', denetci_yonlendirmesi = 'Aşama 1''de piktogram ve kabin panosundaki görsel sinyalin aktifleştiğini ve normal çalışmaya kadar aktif kaldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0780';
update public.madde_kutuphanesi set resmi_madde_metni = 'Aşama 1 başladığı anda ve asansör muayene amaçlı çalışma, acil durumda elektrikle çalışma veya herhangi bir bakım kumandası altında olduğunda işitsel sinyal duyulmalıdır.', kontrol_basligi = 'Aşama 1''de işitsel sinyalin duyulması', denetci_yonlendirmesi = 'Aşama 1 başladığında ve muayene/acil/bakım kumandası altındayken işitsel sinyalin duyulduğunu test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0781';
update public.madde_kutuphanesi set resmi_madde_metni = 'Aşama 1 başladığı anda ve asansör muayene amaçlı çalışma, acil durumda elektrikle çalışma veya herhangi bir bakım kumandası altında olduğunda işitsel sinyal 55 dB (A) olarak ayarlanmış olmalıdır. ( 35 dB (A) ile 65 dB (A) arasında ayarlanabilen bir sistem olmalıdır.)', kontrol_basligi = 'Aşama 1 işitsel sinyal seviyesinin 55 dB(A) ayarı', denetci_yonlendirmesi = 'İşitsel sinyalin 55 dB(A) (35-65 dB(A) ayarlanabilir aralıkta) olarak ayarlandığını ölçün.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0782';
update public.madde_kutuphanesi set resmi_madde_metni = 'İtfaiyeci asansörü muayene amaçlı çalışma durumundan, acil durumda elektrikle çalışma durumundan veya herhangi bakım kumandasından çıkarıldığında, işitsel sinyal iptal edilmeli ve itfaiyeci asansörü otomatik olarak Aşama 1’de çalışmaya devam etmelidir.', kontrol_basligi = 'Muayene/bakım kumandasından çıkışta sinyal iptali ve Aşama 1''e devam', denetci_yonlendirmesi = 'İtfaiyeci asansörü muayene/acil/bakım kumandasından çıkarıldığında işitsel sinyalin iptal edildiğini ve Aşama 1''de otomatik çalışmaya devam ettiğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0783';
update public.madde_kutuphanesi set resmi_madde_metni = 'Durakta park etmiş bir asansör kapılarını kapamalı ve durmaksızın itfaiye hizmeti erişim seviyesine gitmelidir.', kontrol_basligi = 'Durakta park etmiş asansörün itfaiye erişim seviyesine gitmesi', denetci_yonlendirmesi = 'Durakta park etmiş asansörün kapılarını kapayıp durmaksızın itfaiye hizmeti erişim seviyesine gittiğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0784';
update public.madde_kutuphanesi set resmi_madde_metni = 'Durakta park etmiş bir asansörün kapıları kapanana kadar işitsel sinyal kabin içinde duyulmalıdır.', kontrol_basligi = 'Kapı kapanana kadar kabin içi işitsel sinyal', denetci_yonlendirmesi = 'Durakta park etmiş asansörün kapıları kapanana kadar işitsel sinyalin kabin içinde duyulduğunu test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0785';
update public.madde_kutuphanesi set resmi_madde_metni = 'Durakta park etmiş bir asansörün kapılarının açık kalma süresi 15 s’yi aşarsa, ısı ve dumana duyarlı tüm kapı koruma aygıtları devre dışı bırakılmalı ve kapılar azalan bir güçte kapanmaya başlamalıdır.', kontrol_basligi = '15 s sonrası kapı koruma aygıtlarının devre dışı kalması', denetci_yonlendirmesi = 'Kapıların açık kalma süresi 15 saniyeyi aşarsa ısı/duman duyarlı kapı koruma aygıtlarının devre dışı bırakılıp kapıların azalan güçle kapandığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0786';
update public.madde_kutuphanesi set resmi_madde_metni = 'itfaiye hizmeti erişim seviyesinin tersi yöne hareket eden asansör normal olarak durmalı, mümkün olan en yakın durakta kapıları açmadan yönünü değiştirmeli ve itfaiye hizmeti erişim seviyesine geri dönmelidir.', kontrol_basligi = 'Ters yönde hareket eden asansörün yön değiştirmesi', denetci_yonlendirmesi = 'İtfaiye erişim seviyesinin tersi yönde hareket eden asansörün en yakın durakta kapı açmadan yön değiştirip erişim seviyesine döndüğünü test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0787';
update public.madde_kutuphanesi set resmi_madde_metni = 'itfaiye hizmeti erişim seviyesi yönünde hareket eden asansör, durmaksızın itfaiye hizmeti erişim seviyesine doğru hareketine devam etmelidir.', kontrol_basligi = 'Erişim seviyesi yönünde hareketin kesintisiz devamı', denetci_yonlendirmesi = 'İtfaiye erişim seviyesi yönünde hareket eden asansörün durmaksızın erişim seviyesine ulaştığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0788';
update public.madde_kutuphanesi set resmi_madde_metni = 'Eğer asansör bir durakta durmaya başlamışsa, normal şekilde durabilir ve kapılarını açmadan itfaiye hizmeti erişim seviyesine doğru yoluna devam edebilir.', kontrol_basligi = 'Duraktan geçişte kapı açmadan yola devam', denetci_yonlendirmesi = 'Asansör bir durakta durmaya başlamışsa, normal durup kapı açmadan erişim seviyesine devam edebildiğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0789';
update public.madde_kutuphanesi set resmi_madde_metni = 'itfaiyeci asansörü, itfaiye hizmeti erişim seviyesine geldiğinde, kabin ve durak kapıları açık şekilde beklemelidir.', kontrol_basligi = 'Erişim seviyesinde kabin ve durak kapılarının açık beklemesi', denetci_yonlendirmesi = 'İtfaiyeci asansörü erişim seviyesine geldiğinde kabin ve durak kapılarının açık beklediğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0790';
update public.madde_kutuphanesi set resmi_madde_metni = 'İtfaiyeci asansörü, itfaiye hizmeti erişim seviyesinde kapıları açık şekilde durduktan sonra kontrol, tamamen itfaiyeci asansörü kabin kumandalarından yapılmalıdır.', kontrol_basligi = 'Aşama 2''de kontrolün tamamen kabin kumandalarında olması', denetci_yonlendirmesi = 'Aşama 2''de asansörün kontrolünün tamamen itfaiyeci asansörü kabin kumandalarından yapıldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0792';
update public.madde_kutuphanesi set resmi_madde_metni = 'Aşama 1, haricî bir sinyal ile başlatıldığında, durakta bulunan itfaiyeci asansörü anahtarı çalıştırılmadan itfaiyeci asansörü Aşama 2’ye geçmemelidir;', kontrol_basligi = 'Harici sinyalle Aşama 1''de Aşama 2''ye geçilmemesi', denetci_yonlendirmesi = 'Aşama 1 harici sinyalle başlatıldığında, duraktaki itfaiyeci anahtarı çalıştırılmadan Aşama 2''ye geçilmediğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0793';
update public.madde_kutuphanesi set resmi_madde_metni = 'Aşama 2 başlatıldığında kabin içerisinden eş zamanlı olarak birden fazla kabin çağrısını kaydetmek mümkün olmamalıdır.', kontrol_basligi = 'Aşama 2''de eş zamanlı birden fazla çağrı kaydedilmemesi', denetci_yonlendirmesi = 'Aşama 2''de kabin içinden eş zamanlı birden fazla kabin çağrısı kaydedilemediğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0794';
update public.madde_kutuphanesi set resmi_madde_metni = 'Her durumda kabin içerisinden yeni çağrı kaydı mümkün olmalıdır. Bu durumda bir önceki çağrı iptal edilmelidir. Kabin en kısa sürede, yeni çağrı kaydının verildiği durağa hareket etmelidir.', kontrol_basligi = 'Yeni çağrı kaydında önceki çağrının iptali', denetci_yonlendirmesi = 'Kabin içinden yeni çağrı kaydında önceki çağrının iptal edildiğini ve kabinin yeni durağa hareket ettiğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0795';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kabin çağırma düğmesine veya kapı kapatma düğmesine sabit basınç uygulanması, kapının kapanmasını sağlamalıdır. Kapı tamamen kapanmadan önce düğme serbest bırakılırsa, kapı otomatik olarak yeniden açılmalıdır.', kontrol_basligi = 'Kapı kapatma düğmesine sabit basınç ile kapı kapanması', denetci_yonlendirmesi = 'Kapı kapatma düğmesine sabit basınçla kapının kapandığını, erken bırakılırsa otomatik yeniden açıldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0796';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kabin yeni çağrıya sadece asansör kapıları tamamen kapandığında cevap vermeli ve kabin belirlenen yeni durağa doğru hareketine başlamalıdır.', kontrol_basligi = 'Kapı tam kapanınca yeni çağrıya cevap verilmesi', denetci_yonlendirmesi = 'Kabinin yeni çağrıya yalnızca kapılar tam kapandığında cevap verip harekete başladığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0797';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kabin durakta beklerken kapıların açılması, yalnızca kapı açma düğmesine sabit basınç uygulanmasıyla mümkün olmalıdır. Kapıların tam açık duruma gelmesine 50 mm kala kapı açma düğmesi serbest bırakılırsa, kapılar otomatik olarak yeniden kapanmalıdır.', kontrol_basligi = 'Kapı açma düğmesine sabit basınç ile kapı açılması', denetci_yonlendirmesi = 'Durakta bekleyen kabinde kapıların yalnızca kapı açma düğmesine sabit basınçla açıldığını, erken bırakılırsa 50 mm kala yeniden kapandığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0798';
update public.madde_kutuphanesi set resmi_madde_metni = 'Isı ve dumana duyarlı tüm kapı koruma aygıtları devre dışı bırakılmalı ama kabin kapısının hareket yönünü değiştirme aygıtları ve kapı açma düğmesi Aşama 1’deki gibi çalışır durumda kalmalıdır.', kontrol_basligi = 'Aşama 2''de ısı/duman koruma aygıtlarının devre dışı kalması', denetci_yonlendirmesi = 'Aşama 2''de ısı/duman duyarlı kapı koruma aygıtlarının devre dışı kaldığını, kapı yön değiştirme aygıtı ve açma düğmesinin Aşama 1''deki gibi çalıştığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0799';
update public.madde_kutuphanesi set resmi_madde_metni = 'itfaiyeci asansörü, itfaiye hizmeti erişim seviyesindeki itfaiyeci asansörü anahtarı konum “1”den “0”a getirilerek ve tekrar konum “1”e gelmeden en az 5 s bekletilerek itfaiye hizmeti erişim seviyesine geri gelmelidir. (kabin içinde bir anahtarlı şalterin bulunduğu ve kapının açık olduğu durumlar için geçerli değildir)', kontrol_basligi = 'Anahtarın ''1''-''0''-''1'' döngüsüyle erişim seviyesine dönüş', denetci_yonlendirmesi = 'İtfaiyeci asansörünün, anahtar ''1''den ''0''a alınıp en az 5 s sonra tekrar ''1''e getirilerek erişim seviyesine döndüğünü test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0800';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kabin içerisinde anahtarlı şalterin bulunduğu durumlarda, bu anahtar piktogramla işaretlenmeli ve ‘0’ ve ‘1’ konumları açıkça gösterilmelidir. Üçgen anahtar haricindeki herhangi bir anahtar tipi kullanılabilir ancak bu anahtar yalnızca ‘0’ konumunda yerinden çıkarılabilmelidir.', kontrol_basligi = 'Kabin içi anahtarlı şalterin işaretlenmesi', denetci_yonlendirmesi = 'Kabin içinde anahtarlı şalter varsa piktogramla işaretli olduğunu, ''0''/''1'' konumlarının gösterildiğini ve yalnızca ''0''da çıkarılabildiğini kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0801';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kabindeki anahtarlı şalter, asansör, itfaiye hizmeti erişim seviyesindeki anahtar yoluyla itfaiyeci kumandasına geçtiğinde, aşama 2’nin başlaması için ‘1’ konumuna getirilmelidir', kontrol_basligi = 'Kabin içi şalterin Aşama 2 başlatma konumu', denetci_yonlendirmesi = 'Kabindeki anahtarlı şalterin, asansör itfaiyeci kumandasına geçtiğinde Aşama 2''yi başlatmak için ''1'' konumuna getirilmesi gerektiğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0802';
update public.madde_kutuphanesi set resmi_madde_metni = 'asansör, itfaiye hizmeti erişim seviyesi haricindeki bir duraktayken ve kabindeki anahtarlı şalter ‘0’ konumuna getirildiğinde, kabinin hareket etmesi engellenmeli ve kapılar, yalnızca madde 10.7 ’de belirtildiği şekilde çalışmaya devam etmelidir.', kontrol_basligi = 'Kabin içi şalter ''0'' konumunda hareketin engellenmesi', denetci_yonlendirmesi = 'Asansör erişim seviyesi dışındayken kabin şalteri ''0''a alındığında kabinin hareketinin engellendiğini ve kapıların madde 10.7''ye göre çalıştığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0803';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kaydedilen kabin çağrısı, kabin kumanda panosunda görsel olarak belirtilmelidir.', kontrol_basligi = 'Kaydedilen kabin çağrısının görsel gösterimi', denetci_yonlendirmesi = 'Kaydedilen kabin çağrısının kabin kumanda panosunda görsel olarak gösterildiğini kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0804';
update public.madde_kutuphanesi set resmi_madde_metni = 'Güç mevcut olduğunda kabinin konumu, kabin içinde ve itfaiye hizmeti erişim seviyesinde gösterilmelidir.', kontrol_basligi = 'Kabin konumunun kabin içi ve erişim seviyesinde gösterimi', denetci_yonlendirmesi = 'Güç mevcutken kabin konumunun hem kabin içinde hem itfaiye erişim seviyesinde gösterildiğini kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0805';
update public.madde_kutuphanesi set resmi_madde_metni = 'Asansör, yeni bir çağrı kaydedilene kadar, gideceği durakta beklemelidir.', kontrol_basligi = 'Yeni çağrıya kadar durakta bekleme', denetci_yonlendirmesi = 'Asansörün yeni bir çağrı kaydedilene kadar bulunduğu durakta beklediğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0806';
update public.madde_kutuphanesi set resmi_madde_metni = 'İtfaiye hizmeti haberleşme sistemi Aşama 2 süresince çalışır durumda kalmalıdır.', kontrol_basligi = 'Aşama 2''de haberleşme sisteminin çalışır kalması', denetci_yonlendirmesi = 'İtfaiye hizmeti haberleşme sisteminin Aşama 2 süresince çalışır durumda kaldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0807';
update public.madde_kutuphanesi set resmi_madde_metni = 'itfaiyeci anahtarları ''0'' konumuna getirildiğinde, itfaiyeci asansörü kontrol sistemi, normal çalışma durumuna yalnızca asansör, itfaiye hizmeti erişim seviyesine geri geldiğinde geçmelidir.', kontrol_basligi = 'Anahtar ''0''a alınınca normal çalışmaya erişim seviyesinde dönüş', denetci_yonlendirmesi = 'İtfaiyeci anahtarları ''0''a getirildiğinde kontrol sisteminin normal çalışmaya yalnızca asansör erişim seviyesine döndüğünde geçtiğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0808';
update public.madde_kutuphanesi set resmi_madde_metni = 'Tek kabin kumanda panosu olması durumunda; 2 kapı açma düğmesi olmalıdır. Kapı açma düğmelerinin hangi kapıya ait olduğu kolayca teşhis edilebilmelidir.', kontrol_basligi = 'Güvenli alanlar aynı tarafta: tek panelde iki kapı açma düğmesi', denetci_yonlendirmesi = 'Tek kabin kumanda panosunda 2 kapı açma düğmesi olduğunu ve hangi kapıya ait olduklarının kolayca ayırt edildiğini kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0810';
update public.madde_kutuphanesi set resmi_madde_metni = 'Tek kabin kumanda panosu olması durumunda; itfaiye hizmeti erişim seviyesi tarafı için kullanılan kapı açma düğmesi, Aşama 2’de aydınlatılmalıdır.', kontrol_basligi = 'Güvenli alanlar aynı tarafta: kullanılan kapı düğmesinin aydınlatılması', denetci_yonlendirmesi = 'Tek panoda, itfaiye erişim seviyesi tarafı için kullanılan kapı açma düğmesinin Aşama 2''de aydınlatıldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0811';
update public.madde_kutuphanesi set resmi_madde_metni = 'Tek kabin kumanda panosu olması durumunda; itfaiye hizmeti erişim seviyesi tarafı için kullanılmayacak kapı açma düğmesi, Aşama 2’de devre dışı kalmalıdır.', kontrol_basligi = 'Güvenli alanlar aynı tarafta: kullanılmayan kapı düğmesinin devre dışı kalması', denetci_yonlendirmesi = 'Tek panoda, itfaiye erişim seviyesi tarafı için kullanılmayan kapı açma düğmesinin Aşama 2''de devre dışı kaldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0812';
update public.madde_kutuphanesi set resmi_madde_metni = 'Birden çok kabin kumanda panosu olması durumunda; itfaiye hizmeti erişim seviyesi tarafına bitişik olan kabin kumanda panosu, itfaiyeciler tarafından Aşama 2’de kullanılmak içindir ve itfaiyeci asansörü piktogramı ile işaretlenmelidir.', kontrol_basligi = 'Güvenli alanlar aynı tarafta: itfaiyeci panosunun işaretlenmesi', denetci_yonlendirmesi = 'Birden çok panoda, erişim seviyesi tarafına bitişik panonun itfaiyeci kullanımı için piktogramla işaretli olduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0813';
update public.madde_kutuphanesi set resmi_madde_metni = 'Birden çok kabin kumanda panosu olması durumunda; Aşama 2 de kullanılmayacak kabin kumanda panosu devre dışı bırakılmalıdır.', kontrol_basligi = 'Güvenli alanlar aynı tarafta: diğer kumanda panelleri', denetci_yonlendirmesi = 'Birden çok panoda, Aşama 2''de kullanılmayacak kabin kumanda panosunun devre dışı bırakıldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0814';
update public.madde_kutuphanesi set resmi_madde_metni = 'Birden çok kabin kumanda panosu olması durumunda; itfaiyeci asansör kabini kumanda panosunda birden fazla kapı açma düğmesi bulunuyorsa, itfaiye hizmeti erişim seviyesi tarafına karşılık gelen kapı açma düğmesi, Aşama 2’de aydınlatılmalı ve diğer kapı açma düğmesi Aşama 2’de devre dışı bırakılmalıdır.', kontrol_basligi = 'Güvenli alanlar aynı tarafta: birden fazla düğmede aydınlatma ayrımı', denetci_yonlendirmesi = 'Panoda birden fazla kapı açma düğmesi varsa, erişim seviyesi tarafına karşılık gelenin aydınlatıldığını, diğerinin devre dışı kaldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0815';
update public.madde_kutuphanesi set resmi_madde_metni = 'Aşama 2 de İtfaiye asansörünün durduğu katlarda güvenli alana açılmayan kapıların açılması mümkün olmamalıdır.', kontrol_basligi = 'Güvenli alanlar aynı tarafta: diğer taraftaki kapıların kilitlenmesi', denetci_yonlendirmesi = 'Aşama 2''de güvenli alana açılmayan kapıların açılamadığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0816';
update public.madde_kutuphanesi set resmi_madde_metni = 'Tek kabin kumanda panosu olması durumunda; 2 kapı açma düğmesi olmalıdır. Kapı açma düğmelerinin hangi kapıya ait olduğu kolayca teşhis edilebilmelidir.', kontrol_basligi = 'Güvenli alanlar farklı taraflarda: tek panelde iki kapı açma düğmesi', denetci_yonlendirmesi = 'Tek kabin kumanda panosunda 2 kapı açma düğmesi olduğunu ve hangi kapıya ait olduklarının kolayca ayırt edildiğini kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0818';
update public.madde_kutuphanesi set resmi_madde_metni = 'Tek kabin kumanda panosu olması durumunda; belirlenen duraktaki güvenli alanın mevcut tarafı/tarafları, ilgili kapı açma düğmesinin/düğmelerinin aydınlatılmasıyla gösterilmeli ve diğer kapı açma düğmeleri devre dışı bırakılmalıdır.', kontrol_basligi = 'Güvenli alanlar farklı taraflarda: mevcut tarafın aydınlatılması', denetci_yonlendirmesi = 'Tek panoda, belirlenen duraktaki güvenli alanın mevcut tarafının ilgili düğme aydınlatılarak gösterildiğini, diğerinin devre dışı kaldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0819';
update public.madde_kutuphanesi set resmi_madde_metni = 'Birden çok kabin kumanda panosu olması durumunda; kabin kumanda panolarından sadece tek biri, Aşama 2’de itfaiyeciler tarafından kullanılmalı ve itfaiyeci asansörü piktogramı ile işaretlenmelidir.', kontrol_basligi = 'Güvenli alanlar farklı taraflarda: tek panonun itfaiyeci kullanımı', denetci_yonlendirmesi = 'Birden çok panoda, yalnız tek panonun Aşama 2''de itfaiyeciler tarafından kullanıldığını ve piktogramla işaretli olduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0820';
update public.madde_kutuphanesi set resmi_madde_metni = 'Birden çok kabin kumanda panosu olması durumunda; itfaiyecilerin kullandığı kabin kumanda panosu, amaçlanan tüm duraklara hizmet vermeli ve iki kapı açma düğmesine sahip olmalıdır.', kontrol_basligi = 'Güvenli alanlar farklı taraflarda: panonun tüm duraklara ve iki düğmeye sahip olması', denetci_yonlendirmesi = 'İtfaiyecilerin kullandığı panonun amaçlanan tüm duraklara hizmet verdiğini ve iki kapı açma düğmesine sahip olduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0821';
update public.madde_kutuphanesi set resmi_madde_metni = 'Birden çok kabin kumanda panosu olması durumunda; asansör katta dururken, bu seviyedeki mevcut güvenli alan/alanlar, Aşama 2’de ilgili kapı açma düğmesi/düğmeleri ile aydınlatılarak gösterilmeli ve diğer kapı açma düğmeleri devre dışı bırakılmalıdır.', kontrol_basligi = 'Güvenli alanlar farklı taraflarda: katta dururken mevcut tarafın aydınlatılması', denetci_yonlendirmesi = 'Asansör katta dururken mevcut güvenli alan tarafının ilgili düğme ile aydınlatıldığını, diğerinin devre dışı kaldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0822';
update public.madde_kutuphanesi set resmi_madde_metni = 'Birden çok kabin kumanda panosu olması durumunda; asansör hareket hâlindeyken ve bir kabin çağrısı alındığında, belirlenen duraktaki güvenli alanın mevcut tarafı/tarafları, Aşama 2’de ilgili kapı açma düğmesi/düğmeleri ile aydınlatılarak gösterilmelidir.', kontrol_basligi = 'Güvenli alanlar farklı taraflarda: hareket halindeyken mevcut tarafın gösterimi', denetci_yonlendirmesi = 'Asansör hareket halindeyken ve çağrı alındığında, belirlenen duraktaki güvenli alan tarafının aydınlatılarak gösterildiğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0823';
update public.madde_kutuphanesi set resmi_madde_metni = 'Birden çok kabin kumanda panosu olması durumunda; Aşama 2 de kullanılmayacak kabin kumanda panosu devre dışı bırakılmalıdır.', kontrol_basligi = 'Güvenli alanlar farklı taraflarda: diğer kumanda panelleri', denetci_yonlendirmesi = 'Birden çok panoda, Aşama 2''de kullanılmayacak kabin kumanda panosunun devre dışı bırakıldığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0824';
update public.madde_kutuphanesi set resmi_madde_metni = 'Aşama 2 de İtfaiye asansörünün durduğu katlarda güvenli alana açılmayan kapıların açılması mümkün olmamalıdır.', kontrol_basligi = 'Güvenli alanlar farklı taraflarda: diğer taraftaki kapıların kilitlenmesi', denetci_yonlendirmesi = 'Aşama 2''de güvenli alana açılmayan kapıların açılamadığını test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0825';
update public.madde_kutuphanesi set resmi_madde_metni = 'Asansör, aydınlatma ve itfaiye hizmeti haberleşme sistemine ait güç besleme sistemi, birincil ve ikincil (acil durum, yedek veya alternatif) güç beslemelerinden oluşmalıdır. Koruma seviyesi, ulusal düzenlemelere veya gerekliliklere uygun olmalı ve en az asansör kuyusunun koruma seviyesine denk olmalıdır.', kontrol_basligi = 'İtfaiyeci asansörü güç besleme sisteminin birincil/ikincil yapısı', denetci_yonlendirmesi = 'Asansör, aydınlatma ve haberleşme güç besleme sisteminin birincil ve ikincil (acil durum/yedek) beslemelerden oluştuğunu ve koruma seviyesinin en az kuyu koruma seviyesine denk olduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0827';
update public.madde_kutuphanesi set resmi_madde_metni = 'İkincil güç beslemesi, itfaiyeci asansörünü beyan yükünde ve beyan hızında, yangına dayanıklılık süresine denk süre boyunca çalıştırılabilmelidir. Kabin ve kuyu aydınlatması için güç de ikincil güç beslemesi tarafından sağlanmalıdır.', kontrol_basligi = 'İkincil güç beslemesinin çalışma süresi ve aydınlatma kapsamı', denetci_yonlendirmesi = 'İkincil güç beslemesinin beyan yükü/hızında yangına dayanıklılık süresi boyunca çalıştığını ve kabin/kuyu aydınlatmasını da beslediğini doğrulayın.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0828';
update public.madde_kutuphanesi set resmi_madde_metni = 'Güç beslemesi eski hâline geldiğinde asansör 1 dakika içinde kullanıma hazır duruma gelmelidir.', kontrol_basligi = 'Güç geri gelince 1 dakikada hazır olma', denetci_yonlendirmesi = 'Güç beslemesi eski haline geldiğinde asansörün 1 dakika içinde kullanıma hazır duruma geldiğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0829';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kabin ve durak kumandaları ve ilgili kumanda sistemi; ısı, duman, su veya nemin etkisiyle oluşan yanlış sinyalleri kaydetmemelidir.', kontrol_basligi = 'Kumandaların ısı/duman/su/nemden yanlış sinyal almaması', denetci_yonlendirmesi = 'Kabin ve durak kumandalarının ısı, duman, su veya nem etkisiyle yanlış sinyal kaydetmediğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0830';
update public.madde_kutuphanesi set resmi_madde_metni = 'İtfaiye hizmeti erişim seviyesinde kabin konumu göstergesi bulunmalıdır.', kontrol_basligi = 'Erişim seviyesinde kabin konumu göstergesi', denetci_yonlendirmesi = 'İtfaiye hizmeti erişim seviyesinde kabin konumu göstergesi bulunduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0831';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kabin kumandaları, kabin içindeki konum göstergesi, itfaiye hizmeti erişim seviyesi ve itfaiyeci asansörü anahtarındaki konum göstergeleri, EN 60529:1991’e göre en az IPX3 koruma derecesiyle korunmalıdır.', kontrol_basligi = 'Kabin/erişim seviyesi göstergelerinin IPX3 koruması', denetci_yonlendirmesi = 'Kabin kumandaları, kabin içi konum göstergesi ve erişim seviyesi/anahtar göstergelerinin en az IPX3 korumalı olduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0832';
update public.madde_kutuphanesi set resmi_madde_metni = 'İtfaiye hizmeti erişim seviyesi dışındaki seviyelerde bulunan durak kumanda panoları ve durak göstergeleri, itfaiyeci asansörü anahtarı çalıştırıldığında elektriksel olarak devre dışı kalmadığı takdirde, EN 60529:1991’e göre en az IPX3 koruma derecesiyle korunmalıdır.', kontrol_basligi = 'Erişim seviyesi dışı durak panolarının IPX3 koruması', denetci_yonlendirmesi = 'İtfaiye erişim seviyesi dışındaki durak kumanda panoları ve göstergelerinin, elektriksel devre dışı kalmıyorsa en az IPX3 korumalı olduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0833';
update public.madde_kutuphanesi set resmi_madde_metni = 'Aşama 2 kumandasındayken itfaiyeci asansörünün çalışması, kabinde bulunan tam fonksiyonlu basmalı düğmeler veya tuş takımı yoluyla sağlanmalıdır. Tuş takımı, EN 81-70:2018’deki boyut gerekliliklerine uygun olmalı ve basmalı düğme tipinde olmalıdır. Çağrının kabul edildiğini görmek için düğmelere görülebilir şekilde bir geri bildirim gelmelidir.', kontrol_basligi = 'Aşama 2 kumandasının tam fonksiyonlu düğme/tuş takımı ile sağlanması', denetci_yonlendirmesi = 'Aşama 2''de çalışmanın tam fonksiyonlu basmalı düğmeler veya EN 81-70 boyutlarına uygun tuş takımıyla sağlandığını ve düğmelerde görülebilir geri bildirim olduğunu test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0834';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kabindeki normal durak seviyesi işaretlerine ek olarak, Ek G’de gösterilen piktogram kullanılarak, itfaiye hizmeti erişim seviyesi kabin çağırma düğmesi üzerinde veya bitişiğinde itfaiye hizmeti erişim seviyesine ait açık bir gösterim bulunmalıdır.', kontrol_basligi = 'Erişim seviyesi kabin çağırma düğmesinde piktogram gösterimi', denetci_yonlendirmesi = 'Kabinde, itfaiye erişim seviyesi çağırma düğmesi üzerinde veya bitişiğinde Ek G piktogramıyla açık gösterim bulunduğunu kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0835';
update public.madde_kutuphanesi set resmi_madde_metni = 'Kabin ile itfaiye hizmeti erişim seviyesi arasındaki haberleşme, Aşama 1 ve Aşama 2’de kumanda düğmesine basılmaksızın sürekli olarak devrede olmalıdır.', kontrol_basligi = 'Kabin-erişim seviyesi haberleşmesinin sürekli devrede olması', denetci_yonlendirmesi = 'Kabin ile itfaiye hizmeti erişim seviyesi arasındaki haberleşmenin Aşama 1 ve Aşama 2''de düğmeye basılmaksızın sürekli devrede olduğunu test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0836';
update public.madde_kutuphanesi set resmi_madde_metni = 'itfaiyeci asansörü makine dairesi veya makine dairesi bulunmayan asansörlerde acil durum ve test panosu/panoları ile haberleşme birimindeki kumanda düğmesine basılarak etkinleştirilmelidir.', kontrol_basligi = 'Makine dairesi/acil durum panosu haberleşme etkinleştirmesi', denetci_yonlendirmesi = 'İtfaiyeci asansörü makine dairesi veya makine dairesi bulunmayan asansörlerde acil durum/test panosu haberleşme biriminin kumanda düğmesiyle etkinleştiğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0837';
update public.madde_kutuphanesi set resmi_madde_metni = 'Diğer konumlardaki mikrofonlar yalnızca, dâhilî haberleşme birimindeki kumanda düğmesine basılarak etkinleştirilmelidir.', kontrol_basligi = 'Diğer konum mikrofonlarının yalnız düğmeyle etkinleşmesi', denetci_yonlendirmesi = 'Diğer konumlardaki mikrofonların yalnızca dâhili haberleşme biriminin kumanda düğmesine basılarak etkinleştiğini test edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0838';
update public.madde_kutuphanesi set resmi_madde_metni = 'Asansör kabini içerisindeki ve itfaiye hizmeti erişim seviyesindeki haberleşme donanımı, gömülütip mikrofon ve hoparlör olmalı, telefon ahizesi şeklinde olmamalıdır.', kontrol_basligi = 'Haberleşme donanımının gömülü mikrofon/hoparlör tipinde olması', denetci_yonlendirmesi = 'Kabin ve erişim seviyesindeki haberleşme donanımının gömülü tip mikrofon/hoparlör olduğunu, telefon ahizesi tipinde olmadığını kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0839';
update public.madde_kutuphanesi set resmi_madde_metni = 'Haberleşme sisteminin kablo bağlantısı, asansör kuyusu içerisinde tesis edilmelidir.', kontrol_basligi = 'Haberleşme kablo bağlantısının kuyu içinde tesisi', denetci_yonlendirmesi = 'Haberleşme sisteminin kablo bağlantısının asansör kuyusu içerisinde tesis edildiğini kontrol edin.', kaynak_form_kodu = 'ÜB.FR.40', kaynak_form_revizyonu = 'R.04' where madde_id = 'MAD-0840';

update public.madde_kutuphanesi set aktif = false where madde_id in ('MAD-0791','MAD-0809','MAD-0817','MAD-0826','MAD-0841','MAD-0842','MAD-0843','MAD-0844');

